export class SpeedEffects{
 constructor(canvas,board,windows){this.canvas=canvas;this.board=board;this.windows=windows;this.ctx=canvas.getContext('2d',{alpha:true});this.resizeObserver=new ResizeObserver(()=>this.resize());this.resizeObserver.observe(board);this.resize()}
 resize(){const b=this.board.getBoundingClientRect();this.canvas.width=Math.round(b.width);this.canvas.height=Math.round(b.height);this.views=this.windows.map(e=>{const r=e.getBoundingClientRect();return {x:r.left-b.left,y:r.top-b.top,w:r.width,h:r.height}})}
 frame(players,clock){const c=this.ctx;if(!c)return;c.clearRect(0,0,this.canvas.width,this.canvas.height);for(const p of players){if(!p.boostLevel||p.finishTime!==null)continue;const v=this.views[p.lane],level=p.boostLevel,focus=[v.w*.48,v.h*.43],speed=p.speed/60,count=12+level*6;c.save();c.translate(v.x,v.y);c.beginPath();c.rect(0,0,v.w,v.h);c.rect(v.w*.10,v.h*.53,v.w*.46,v.h*.43);c.clip('evenodd');for(let j=0;j<count;j++){const angle=j*Math.PI*2/count+.09*Math.sin(j*7.1),cycle=(clock*(.7+speed*.9)+j*.618)%1,r0=Math.min(v.w,v.h)*(.42+cycle*.67),length=(24+level*17+cycle*28)*v.h/668,x=Math.cos(angle),y=Math.sin(angle)*1.55;c.strokeStyle=j%3===0?'rgba(255,227,157,.40)':`rgba(244,252,255,${(.12+cycle*.2+level*.03).toFixed(2)})`;c.lineWidth=j%4===0?1.9:1.05;c.beginPath();c.moveTo(focus[0]+x*r0,focus[1]+y*r0);c.lineTo(focus[0]+x*(r0+length),focus[1]+y*(r0+length));c.stroke()}c.restore()}}
 destroy(){this.resizeObserver.disconnect()}
}
